def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 96:
        opp_recent = [h[1] for h in history[-10:]]
        opp_c = sum(1 for a in opp_recent if a == 'C')
        if opp_c >= 7:
            return 'D'
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for a in me if a == 'C')
    last_me = me[-1]
    last_opp = opp[-1]
    if n <= 2:
        return 'C'
    if opp_d == 0:
        return 'C'
    if opp_c == 0:
        return 'D'
    window = min(15, n)
    recent = opp[-window:]
    recent_d = sum(1 for a in recent if a == 'D')
    recent_c = window - recent_d
    rate = recent_c / float(window)
    if recent_d >= window - 1:
        if rng.random() < 0.1:
            return 'C'
        return 'D'
    if rate >= 0.85:
        if rng.random() < 0.06:
            return 'D'
        return 'C'
    if rate >= 0.6:
        if last_opp == 'D':
            return 'D'
        return 'C'
    if rate >= 0.35:
        if last_opp == 'D':
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        return 'C'
    if last_opp == 'D' and last_me == 'D':
        if recent_d >= window * 3 // 4:
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        return 'C' if rng.random() < 0.25 else 'D'
    if rng.random() < 0.1:
        return 'C'
    return 'D'
